function validate(input) {
  const [{ Triangle = [] }] = input;
  const seen = new Set();
  for (const [x, y, z] of Triangle) {
    if (x === null || y === null || z === null) return 'Every length must be given.';
    if (x <= 0 || y <= 0 || z <= 0) return `Lengths must be positive (${x}, ${y}, ${z}).`;
    const key = `${x},${y},${z}`;
    if (seen.has(key)) return `(${key}) appears twice.`;
    seen.add(key);
  }
  return null;
}

