function generate(rand, size) {
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const top = size === 'small' ? 8 : 1000;
  const seen = new Set(), Triangle = [];
  let tries = 0;
  while (Triangle.length < rows && tries++ < rows * 20) {
    let x = 1 + Math.floor(rand() * top), y = 1 + Math.floor(rand() * top), z;
    const pick = rand();
    // Mix flat triples (one side equals the sum of the others), clear triangles and clear failures.
    if (pick < 0.25) z = x + y;
    else if (pick < 0.4) z = Math.max(1, Math.abs(x - y));
    else z = 1 + Math.floor(rand() * top);
    const triple = [x, y, z];
    // Put the longest side in a random position.
    const k = Math.floor(rand() * 3);
    [triple[2], triple[k]] = [triple[k], triple[2]];
    const key = triple.join(',');
    if (seen.has(key)) continue;
    seen.add(key);
    Triangle.push(triple);
  }
  return [{ Triangle }];
}
